package com.sky.controller.admin;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.util.Collections;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.core.ValueOperations;

import com.sky.result.Result;
import com.sky.service.DishService;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：status为1时，应成功启用菜品并清除缓存")
    void startOrStop_EnableDish_ShouldReturnSuccessAndClearCache() {
        // Arrange
        Integer status = 1;
        Long id = 100L;
        Set<String> mockKeys = Collections.singleton("dish_100");
        when(redisTemplate.keys("dish_*")).thenReturn(mockKeys);
        when(redisTemplate.delete(mockKeys)).thenReturn(1L);
        doNothing().when(dishService).startOrStop(status, id);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertTrue(result.isSuccess());
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(mockKeys);
    }

    @Test
    @DisplayName("正向测试：status为0时，应成功停用菜品并清除缓存")
    void startOrStop_DisableDish_ShouldReturnSuccessAndClearCache() {
        // Arrange
        Integer status = 0;
        Long id = 200L;
        Set<String> mockKeys = Collections.singleton("dish_200");
        when(redisTemplate.keys("dish_*")).thenReturn(mockKeys);
        when(redisTemplate.delete(mockKeys)).thenReturn(1L);
        doNothing().when(dishService).startOrStop(status, id);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertTrue(result.isSuccess());
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(mockKeys);
    }

    @Test
    @DisplayName("边界测试：当没有相关缓存键时，应正常执行但不调用delete")
    void startOrStop_WithNoCacheKeys_ShouldNotCallDelete() {
        // Arrange
        Integer status = 1;
        Long id = 300L;
        when(redisTemplate.keys("dish_*")).thenReturn(Collections.emptySet());
        doNothing().when(dishService).startOrStop(status, id);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertTrue(result.isSuccess());
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate, never()).delete(any());
    }

    @Test
    @DisplayName("空值测试：当id为null时，应正常调用服务层并处理")
    void startOrStop_WithNullId_ShouldStillCallService() {
        // Arrange
        Integer status = 1;
        Long id = null;
        Set<String> mockKeys = Collections.singleton("dish_null");
        when(redisTemplate.keys("dish_*")).thenReturn(mockKeys);
        when(redisTemplate.delete(mockKeys)).thenReturn(1L);
        doNothing().when(dishService).startOrStop(status, id);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertTrue(result.isSuccess());
        verify(dishService).startOrStop(status, id);
        verify(redisTemplate).keys("dish_*");
        verify(redisTemplate).delete(mockKeys);
    }
}
